  'monitoring.applications.state.email_verified': 'New',
  'monitoring.applications.state.under_review': 'Under review',
  'monitoring.applications.state.approved': 'Approved, inviting',
  'monitoring.applications.state.rejected': 'Rejected',
  'monitoring.applications.state.provisioned': 'Invite sent',
  'monitoring.applications.state.active': 'Active',
