  // p5-8h begin
  // Reports (C207): a fixed list of tables by role, each for a span of days, with a total row and a CSV.
  'moduleOff.reports': '“Reports” leaves the menu of the office, the accountant and the coordinator. No report can be opened or downloaded. The records each report reads are kept in their own modules.',
  'rpt.page.title': 'Reports',
  'rpt.page.purpose': 'Tables for the days you choose, with totals and a CSV.',
  'rpt.page.info': 'Tables about your school for the days you choose, each with a total row and a CSV file of exactly the same rows.',
  'tour.reports.1.title': 'Your reports',
  'tour.reports.1.text': 'Each report is one table about your school. You see only the reports your role may read.',
  'tour.reports.2.title': 'Choose the days',
  'tour.reports.2.text': '“Today”, “7 days”, “30 days” or two dates of your own. The table and its total are worked out again for those days.',
  'tour.reports.3.title': 'The total and the file',
  'tour.reports.3.text': 'The last row adds up the rows above it. “Download CSV” saves exactly these rows, and each download is recorded.',
  'rpt.list.title': 'Your reports',
  'rpt.list.how': 'Choose a report to open it below. Each one is counted from your school’s own records at the moment you open it.',
  'rpt.group.money': 'Fees',
  'rpt.group.learning': 'Attendance and homework',
  'rpt.group.parents': 'Messages to parents',
  'rpt.group.staff': 'Staff',
  'rpt.failed': 'The reports could not be loaded. Reload the page to try again.',
  'rpt.none.title': 'There is no report for your role',
  'rpt.none.do': 'Reports are for the principal, the school admin, the accountant and the academic coordinator. Your own work for today is on My Day.',
  'rpt.noneOn.title': 'No report is switched on for your school yet',
  'rpt.noneOn.do': 'A report appears here when the module it reads is switched on for your school. To ask for one, raise a ticket from Help.',
  'rpt.choose': 'Choose a report above.',
  'rpt.loading': 'Working it out…',
  'rpt.range.label': 'Days to show',
  'rpt.range.dates': 'Two dates',
  'rpt.range.from': 'From',
  'rpt.range.to': 'To',
  'rpt.range.show': 'Show these days',
  'rpt.range.now': 'About how things stand now, not a span of days.',
