  'rpt.download': 'Download CSV',
  'rpt.download.how': 'The file has exactly these rows and this total. Each download is written to the audit trail: who, which report and which days.',
  'rpt.why.total': 'The total row is the rows above it added up, unless the rule above says otherwise; a rate is worked out again from those sums.',
  'rpt.why.source': 'Read from: {sources}.',
  'rpt.why.version': 'Rule version {version}.',
  'rpt.err.range': 'Choose two real dates, the first not after the second, at most 366 days apart.',
  'rpt.err.too_many_rows': 'These days hold more rows than one report reads. Choose fewer days.',
