  'rpt.daily-collection.title': 'Daily collection',
  'rpt.daily-collection.about': 'A row a day: the receipts issued, the amount, and how it was paid. Reversed receipts are shown apart.',
  'rpt.daily-collection.rule': 'A row for each day a receipt was issued, by India’s date. A receipt reversed later counts for nothing in the amounts and is counted in its own column. The total is the dashboard’s “Fees received” for the same days.',
  'rpt.daily-collection.empty.title': 'No receipt was issued in these days',
  'rpt.daily-collection.empty.do': 'Take a payment in Fees and its day shows here. To look further back, choose more days.',
  'rpt.dues.title': 'Dues and defaulters',
  'rpt.dues.about': 'A row a family, or a child with no family on record, with a fee past its date: what is owed, since when, and the office’s last follow-up.',
  'rpt.dues.rule': 'A fee is overdue when its date has passed, by India’s date, and something is still owed on it. A row adds up one family’s overdue entries. The longest wait comes first, never the largest amount. The total is the dashboard’s “Fees overdue”.',
  'rpt.dues.empty.title': 'No fee is overdue',
  'rpt.dues.empty.do': 'Nothing is past its date with money still owed. When a fee passes its date unpaid, the family shows here.',
  'rpt.dues.notSetUp.title': 'Fees are not set up yet',
  'rpt.dues.notSetUp.do': 'No fee has been raised for your school yet, so nothing can be overdue. Raise a month’s dues in Fees, and a family whose fee passes its date unpaid shows here.',
  'rpt.dues.note.followups': 'The follow-up list holds {count} families. For a family past that, open Fees to see its last follow-up.',
  'rpt.attendance-by-class.title': 'Attendance by class',
  'rpt.attendance-by-class.about': 'A row a class: the days marked, the marks by kind, and the share in school.',
  'rpt.attendance-by-class.rule': 'Every mark saved in these days, under the class it was saved for. In school is present or late, out of every mark; a day on leave is marked and is not an absence. Classes come in the order of their names. The total rate is the dashboard’s “In school, of those marked”. “Days marked” in the total row is not the classes added up: it is the days on which any class was marked, so a day two classes were marked on is one day.',
  'rpt.attendance-by-class.empty.title': 'No attendance was marked in these days',
  'rpt.attendance-by-class.empty.do': 'Mark a class in Attendance and it shows here. To look further back, choose more days.',
  'rpt.absentees.title': 'Absentees',
  'rpt.absentees.about': 'A row a student marked absent in these days: the class, how many days, and the dates.',
  'rpt.absentees.rule': 'A student is listed when marked absent on a day of these days. Late and on leave are not absences. Rows come by class and then by name, never by the number of days.',
  'rpt.absentees.empty.title': 'Nobody was marked absent in these days',
  'rpt.absentees.empty.do': 'When a student is marked absent in Attendance, they show here with the dates. To look further back, choose more days.',
  'rpt.homework-coverage.title': 'Homework coverage',
  'rpt.homework-coverage.about': 'A row a class: homework given out, how much of what fell due was checked, and how often a student was marked not done.',
  'rpt.homework-coverage.rule': 'Given out: homework set in these days. Fell due: homework due in these days for a section with a student on its roll. Checked for everyone: marked for every student of the section. Marked not done: each time a student was marked not done.',
  'rpt.homework-coverage.empty.title': 'No homework was given out or fell due in these days',
  'rpt.homework-coverage.empty.do': 'Set homework for a class in Homework and the class shows here. To look further back, choose more days.',
  'rpt.pulse-coverage.title': 'Daily Pulse coverage',
  'rpt.pulse-coverage.about': 'A row a class: the Daily Pulse messages sent, how many went out to parents, and what parents answered.',
  'rpt.pulse-coverage.rule': 'The Daily Pulse messages a person sent for the lessons of these days, by class. Went out: put in the queue for parents. Held back: stopped before sending. Understood and needs help are the parents’ replies of 1 and 2.',
  'rpt.pulse-coverage.empty.title': 'No Daily Pulse message was sent for these days',
  'rpt.pulse-coverage.empty.do': 'A teacher sends the day’s message from Daily Pulse, and its class shows here. To look further back, choose more days.',
  'rpt.messages-by-state.title': 'Messages by state',
  'rpt.messages-by-state.about': 'A row a day: the WhatsApp messages written that day, by where each one is now. Counts only: no name and no phone number.',
  'rpt.messages-by-state.rule': 'The school’s WhatsApp messages written on each day, by India’s date, by the state each is in now. Held back means stopped before sending: no consent, quiet hours, the monthly limit, or no approved template.',
  'rpt.messages-by-state.empty.title': 'No WhatsApp message was written in these days',
  'rpt.messages-by-state.empty.do': 'A day shows here once the school sends a message: an absence notice, a Daily Pulse message or a fee reminder. To look further back, choose more days.',
  'rpt.staff-leave.title': 'Staff leave',
  'rpt.staff-leave.about': 'A row a leave that was approved and has a day in these days: who, its first and last day, and how many of its days fall inside the days shown.',
  'rpt.staff-leave.rule': 'Approved leave with a day inside these days, one row a leave. Leave that is waiting, refused or withdrawn is not listed. Rows come in the order of the first day, then the name. Leave is not added up by person, and the kind of leave and the reason are not shown here.',
  'rpt.staff-leave.empty.title': 'Nobody has approved leave in these days',
  'rpt.staff-leave.empty.do': 'When leave is approved in Staff, it shows here with its dates. To look ahead or further back, choose two dates.',
  // p5-8h end
  // p5-8i begin
  // School Health Auditor v1 (C208).
  'moduleOff.school-auditor': '“School Health Auditor” leaves the office’s menu. Nobody can run a check-up or open the past ones. Check-ups already recorded are kept.',
  'aud.page.title': 'School Health Auditor',
  'aud.page.purpose': 'A check-up of your records by fixed rules, and where to fix what it finds.',
  'aud.page.about': 'A check-up of your school’s own records by fixed rules: what passes, what needs attention, and the screen that fixes it.',
  'aud.how': 'Rules only: each check is counted from your school’s own records by a fixed rule. No AI model is used, and nothing is scored, graded or ranked.',
  'aud.failed': 'The check-ups could not be loaded. Reload the page.',
  'aud.empty.title': 'No check-up yet',
  'aud.empty.do': 'A check-up reads twelve things in your records and says what passes, what needs attention (with a count and the screen that fixes it) and what is not set up yet.',
  'aud.run.first': 'Run the first check-up',
