  // p5-8j begin
  // Early Warning v1 (docs/26 slice 8j, C209): flags for staff, by rules. A flag is a reason to look, not a verdict.
  'moduleOff.early-warning': '“Early Warning” leaves the menu. Nobody can run the check or add what was done, teachers no longer see their classes’ flags, and its cards leave My Day. Flags on record are kept.',
  'tour.early-warning.1.title': 'A flag is a reason to look',
  'tour.early-warning.1.text': 'A flag says attendance, homework, a needs-help follow-up or exam marks are worth a look. It is not a verdict about the child.',
  'tour.early-warning.2.title': 'Every flag says why',
  'tour.early-warning.2.text': '“Why this?” shows the days and homeworks it rests on, the rule and its version, and when it was last checked.',
  'tour.early-warning.3.title': 'Write what was done',
  'tour.early-warning.3.text': 'Add the step you took and what came of it. A flag closes by itself when its reasons are gone. Nothing goes to a parent.',
  'today.flags-no-action.todo.one': '{count} early-warning flag has no step written yet',
  'today.flags-no-action.todo.other': '{count} early-warning flags have no step written yet',
  'today.flags-no-action.action': 'Open Early Warning',
  'today.flags-no-action.why': 'A flag is open for a child and nobody has written what was done about it. A flag is a reason to look, not a verdict.',
  'today.flags-own-classes.todo.one': '{count} child in your classes has a flag open',
  'today.flags-own-classes.todo.other': '{count} children in your classes have a flag open',
  'today.flags-own-classes.action': 'See the flags',
  'today.flags-own-classes.why': 'The school’s check found a reason to look at attendance, homework, a needs-help follow-up or exam marks for a child you teach. Open it to see why, and to write what you did.',
  'set.early-warning.attendance_below.label': 'In school on fewer than this many days in every 100',
  'set.early-warning.attendance_below.help': 'Attendance becomes a reason to look when a child was in school, present or late, on fewer than this many of every 100 days marked, from 1 to 100. Days on recorded leave are left out.',
  'set.early-warning.window_days.label': 'Looking back this many days',
  'set.early-warning.window_days.help': 'How many days back attendance is counted, today included, from 7 to 90, and never fewer than the days that must be marked below.',
  'set.early-warning.min_marked_days.label': 'Only when at least this many days were marked',
  'set.early-warning.min_marked_days.help': 'Attendance is not used until this many of those days have a mark other than leave, from 1 to 60, and never more than the days looked back above. With fewer days, one or two absences would look larger than they are.',
  'ew.page.title': 'Early Warning',
  'ew.page.purpose': 'Children who may need a look, with why and what was done.',
  'ew.page.about': 'Children whose attendance, homework, a needs-help follow-up or exam marks give a reason to look, with why, and what was done.',
  'ew.failed': 'Early Warning could not be loaded. Check your connection and open the page again.',
  'ew.err.other': 'That did not work. Nothing was changed. Try again.',
  'ew.err.kind': 'Choose what was done from the list.',
  'ew.err.note': 'The note is too long. Keep it within {max} characters.',
  'ew.err.outcome': 'What came of it is too long. Keep it within {max} characters.',
  'ew.err.say_what': 'For “Something else”, write what was done in the note.',
  'ew.err.elsewhere': 'This account was made at another school. A check and a step here are kept in the name of an account made at this school, so this one cannot run the check or add what was done yet.',
  'ew.what.title': 'What a flag is',
  'ew.what.text': 'A flag is a reason to look at how a child is getting on. It is not a verdict about the child. It comes from rules only: attendance, homework, open needs-help follow-ups and exam marks. Fees are never used.',
  'ew.what.staffOnly': 'Flags are for staff. Nothing on this page is sent to a parent.',
  'ew.what.order': 'Every list here is in the order of class and name. None of them is a ranking.',
  'ew.check.title': 'The school’s check',
  'ew.check.how': 'A check looks at every active student. It opens a flag where it finds a reason, brings open flags up to date, and closes a flag when its reasons are gone. It runs by itself each night just after midnight, and whenever a person presses the button.',
  'ew.check.never': 'No check has been run yet.',
