  'ew.open.empty.partial.title': 'No flag is open among the children the check could look at',
  'ew.open.empty.partial.do': 'It could use attendance for {used} of the {students} students it looked at: the others have fewer than {min} days marked in the last {days} days, so nothing is said about their attendance. Mark attendance every school day, then press “Check now”.',
  'ew.open.empty.no_attendance.title': 'No flag is open, and attendance could not be checked',
  'ew.open.empty.no_attendance.do': 'The check could not use attendance for any child: nobody has {min} days marked in the last {days} days. Homework, needs-help follow-ups and exam marks gave no reason. Mark attendance every school day; when {min} days are marked, press “Check now”.',
  'ew.open.empty.teacher.title': 'No flag is open for your classes',
