  'tour.marking.1.title': 'Four steps, top to bottom',
  'tour.marking.1.text': 'Questions, then the class’s scripts, then progress, then the review list. Start with the questions.',
  'tour.marking.2.title': 'Upload the scripts',
  'tour.marking.2.text': 'Choose PDFs or photos. Your device makes the pictures. Press “Mark these” when all are sent.',
  'tour.marking.3.title': 'Check, then approve',
  'tour.marking.3.text': 'Open a script to change marks. “Approve all ready” takes only scripts with nothing to check.',
  'tour.marking-review.1.title': 'Pages and marks',
  'tour.marking-review.1.text': 'The marks sit in the margin of each answer. Press “Show on the page” to see a question’s answer.',
  'tour.marking-review.2.title': 'Change what is wrong',
  'tour.marking-review.2.text': 'Use − and + for half marks, or type a mark. The AI’s steps and reason are under each mark.',
  'tour.marking-review.3.title': 'Approve',
  'tour.marking-review.3.text': '“Approve” puts the marks into the paper’s marks. “Approve and next” goes on to the next script.',
  'tour.exam-numbers.1.title': 'Print and hand out',
  'tour.exam-numbers.1.text': 'The list is in roll order. Press “Print this list” to put the numbers on the desks.',
  'tour.marking-scan.1.title': 'One child at a time, in roll order',
  'tour.marking-scan.1.text': 'Hold the phone over the sheet. It takes the page when held still, or tap to take it. Then Next child: no typing.',
  'tour.marking-scan.2.title': 'Absent, Skip or another child',
  'tour.marking-scan.2.text': 'One tap each. If the sheet shows another child’s name or number, the script is flagged for you, never moved.',
  'tour.marking-scan.3.title': 'Keep scanning, it sends itself',
  'tour.marking-scan.3.text': 'Pages wait on this phone and send in the background, even offline. Each leaves the phone once it arrives.',
  'tour.progress-report.1.title': 'One child, the whole session',
  'tour.progress-report.1.text': 'Every published assessment of this child this session, grouped by exam type. Nothing here ranks or compares children.',
  'tour.progress-report.2.title': 'From published marks only',
  'tour.progress-report.2.text': 'Only classes whose result is published count. A class reopened for a correction leaves the report until it is published again.',
  'tour.progress-report.3.title': 'Print or share',
  'tour.progress-report.3.text': 'Download the PDF for the file. Families see it in the Family app as soon as the result is published.',
