  // Learning Genome v1 (docs/27 row 9e, C217): one child's own exams, homework and Pulse replies, for staff only.
  'moduleOff.learning-genome': '“Learning Genome” leaves the menu and nobody can open a child’s genome. It stores nothing, so nothing is lost: marks, homework and replies stay where they are.',
  'tour.learning-genome.1.title': 'Pick a class, then a child',
  'tour.learning-genome.1.text': 'A teacher sees the children of their own classes. The office and the academic coordinator see every class.',
  'tour.learning-genome.2.title': 'Compared only with themselves',
  'tour.learning-genome.2.text': 'Strengths and gaps hold the child against their own earlier exam, their own overall and their own replies. Never another child.',
  'tour.learning-genome.3.title': 'Every number says where it is from',
  'tour.learning-genome.3.text': 'A percent shows its marks, homework its checks, a chapter the replies it counts, and each rule the line set in Settings.',
  'set.exams.ai_marking_on.label': 'AI marks answer sheets',
  'set.exams.ai_marking_on.help': 'On: teachers may upload a class’s answer sheets for the AI to mark, and then check and approve every mark themselves. Off: nobody uploads answer sheets, and marks are typed as before.',
  'set.exams.review_below.label': 'Ask the teacher to check a script when the AI is less sure than this, in every 100',
  'set.exams.review_below.help': 'A script with any answer the AI was less sure of than this is flagged, and must be checked and approved on its own, from 50 to 95.',
  'set.exams.families_see_scripts.label': 'Families see the checked answer sheets',
  'set.exams.families_see_scripts.help': 'On: once a class’s result is published, its linked families and the private result link show each paper’s checked pages, the marks of every question and the teacher’s notes, for their own child only. Off: families see the published marks only.',
  'set.exams.children_see_results.label': 'Children see their own published results in the Family app',
  'set.exams.children_see_results.help': 'On: a linked child’s own view shows their published results, checked answer sheets (when families see them) and what to practise. Off: only the parent sees them.',
  'set.exams.exam_types.label': 'Exam types',
  'set.exams.exam_types.help': 'The kinds of exam this school holds, in English and Hindi. Rename, hide or add one; each exam names one type. “Other” is always kept.',
