  'set.learning-genome.mistake_min_questions.help': 'On the Learning Genome, a kind of mistake (a slip in a calculation, an answer left unfinished and the like) is listed as coming back when it cost the child marks in at least this many answers, from 2 to 50.',
  'set.learning-genome.mistake_min_papers.label': 'and across at least this many papers',
  'set.learning-genome.mistake_min_papers.help': 'The answers must come from at least this many different papers, so one hard paper does not look like a habit, from 1 to 20.',
