  // Question papers from what was taught, the school's question bank, keeping and printing a paper (docs/36, C362, C363).
  'set.exams.paper_blueprints.label': 'Question paper blueprints',
  'set.exams.paper_blueprints.help': 'One row for each exam type whose papers are made from what was taught: its total marks, its time in minutes, how many questions in every 100 are easy, medium and hard (adding up to 100), which chapters it covers (since_last_of_type: taught since the last paper of the same type; session: taught this session; whole_map: the whole syllabus map) and how the chapters share the marks (periods: by the periods taught; equal: the same for each).',
