  'set.exams.paper_sections.help': 'The sections of each blueprint, A to H: the kind of question (objective, short, long, numerical or diagram), how many questions, the marks of each, and "answer any" for an internal choice (0: every question is answered). A blueprint’s sections add up to its total marks.',
