  'control.ai.profile.name.exams.write_questions': 'Question papers: writing questions',
  'control.ai.profile.about.exams.write_questions': 'Writes the questions of a school’s question paper for the chapters and topics its plan names, with an answer key and marking steps for each. It is sent the class level, the subject, the language and the syllabus only, never a child’s name or work. Its questions are drafts until a teacher keeps the paper.',
  'pp.title': 'Make the paper from what was taught',
  'pp.how': 'The chapters come from the class’s “taught today” log for this subject, by the exam’s type. Each chapter’s marks follow the periods spent on it (or are equal, or the marks you type). The paper’s shape is the exam type’s blueprint. Questions come from the school’s question bank first; the AI writes the rest, each with its answer key and marking steps. Nothing prints until you keep the paper.',
